// ProcessDepositLog: no address check
func (s *Service) ProcessDepositLog(ctx context.Context, depositLog *gethtypes.Log) error {
	pubkey, withdrawalCredentials, amount, signature, merkleTreeIndex, err :=
		contracts.UnpackDepositLogData(depositLog.Data) // no depositLog.Address verification
	...
	index := int64(binary.LittleEndian.Uint64(merkleTreeIndex))
	if index <= s.lastReceivedMerkleIndex { return nil }
	if index != s.lastReceivedMerkleIndex+1 { return errors.Errorf("received incorrect merkle index...") }
	s.lastReceivedMerkleIndex = index
	// inserts into depositTrie and depositCache
}

